mapper.select:
SELECT t1.id, t1.user_name, t1.user_department_name, t1.user_post_name, t2.market_tenant, t3.market_name, t1.user_sign_time, t1.user_sign_status, t1.belated, t2.`name` as task_name, t2.cultivate_mode, t2.source_key, t2.cultivate_start_time, t2.cultivate_end_time, t2.theme_name, t2.charge_user_name FROM cultivate_task_user t1 LEFT JOIN cultivate_task t2 on t1.cultivate_task_id = t2.id LEFT JOIN headquarters_cultivate_task_market t3 on t2.source_key = t3.headquarters_cultivate_task_id AND t2.market_tenant = t3.market_tenant_code
and t1.cultivate_task_id = #{param.cultivateTaskId}
and t2.theme_id = #{param.themeId}
and t2.cultivate_mode = #{param.cultivateMode}
and t1.user_sign_status = #{param.userSignStatus}
and t2.market_tenant = #{param.marketTenant}
and t2.cultivate_start_time >= #{param.period.begin}
and t2.cultivate_start_time <= #{param.period.end}
and t1.belated = #{param.belated}
GROUP BY t1.id order by t1.create_time desc

SELECT t1.id, t1.user_name as `name`, t1.user_department_name as department_name, t1.user_post_name as post_name, t2.market_tenant, t3.market_name, t1.user_sign_time as sign_date, t1.user_sign_status as `status`, t1.belated, t2.`name` AS task_name, t2.cultivate_mode, t2.source_key, t2.cultivate_start_time as start_time, t2.cultivate_end_time as end_time, t2.theme_name, t2.charge_user_name FROM cultivate_task_user t1 LEFT JOIN cultivate_task t2 ON t1.cultivate_task_id = t2.id LEFT JOIN headquarters_cultivate_task_market t3 ON t2.source_key = t3.headquarters_cultivate_task_id AND t2.market_tenant = t3.market_tenant_code
and t1.cultivate_task_id = #{param.cultivateTaskId}
and t2.theme_id = #{param.themeId}
and t2.cultivate_mode = #{param.cultivateMode}
and t1.user_sign_status = #{param.userSignStatus}
and t2.market_tenant = #{param.marketTenant}
and t2.cultivate_start_time >= #{param.period.begin}
and t2.cultivate_start_time <= #{param.period.end}
and t1.belated = #{param.belated}
GROUP BY t1.id order by t1.create_time desc
